<?php use Luna\Core\Auth;use Luna\Core\Csrf;use Luna\Core\View;$token=View::e(Csrf::token());?>
<div class="page-intro"><div><span class="eyebrow">People operations</span><h1>Ferie, approvazioni e paghe</h1><p>Richieste, saldi e un payroll controllato che non può essere chiuso senza validazione professionale.</p></div></div>
<section class="card form-card"><div class="card-header"><h2>Nuova richiesta</h2></div><form method="post" action="/operations/hr/leave" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><?php if($admin):?><label class="field">Dipendente<select name="user_id"><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= View::e($u['name']) ?></option><?php endforeach;?></select></label><?php endif;?><label class="field">Tipo<select name="leave_type"><option>HOLIDAY</option><option>PERMIT</option><option>ROL</option><option>SICK</option><option>OTHER</option></select></label><label class="field">Dal<input type="datetime-local" name="starts_at" required></label><label class="field">Al<input type="datetime-local" name="ends_at" required></label><label class="field">Ore richieste<input type="number" name="requested_hours" min="0.25" step="0.25" required></label><label class="field">Motivazione<input name="reason"></label><div class="form-actions full-width"><button class="button primary">Invia richiesta</button></div></form></section>
<section class="card"><div class="card-header"><h2>Richieste e decisioni</h2></div><div class="table-wrap"><table><thead><tr><th>Dipendente</th><th>Tipo</th><th>Dal</th><th>Al</th><th>Ore</th><th>Stato</th><th>Decisione</th></tr></thead><tbody><?php foreach($leaves as $l):?><tr><td class="primary-cell"><?= View::e($l['user_name']) ?></td><td><?= View::e($l['leave_type']) ?></td><td><?= View::date($l['starts_at']) ?></td><td><?= View::date($l['ends_at']) ?></td><td><?= View::e($l['requested_hours']) ?></td><td><span class="badge status-<?= strtolower($l['status']) ?>"><?= View::e($l['status']) ?></span></td><td><div class="inline-actions"><?php if($admin&&$l['status']==='SUBMITTED'):?><form method="post" action="/operations/hr/leave/<?= (int)$l['id'] ?>/decide" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input name="notes" placeholder="Nota"><button class="button primary" name="decision" value="approve">Approva</button><button class="button" name="decision" value="reject">Rifiuta</button></form><?php endif;?><?php if(in_array($l['status'],['SUBMITTED','APPROVED'],true)&&($admin||(int)$l['user_id']===Auth::id())):?><form method="post" action="/operations/hr/leave/<?= (int)$l['id'] ?>/cancel" onsubmit="return confirm('Annullare la richiesta?')"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button danger">Annulla</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($admin):?><div class="two-columns"><section class="card"><div class="card-header"><h2>Saldi ferie e permessi</h2></div><form method="post" action="/operations/hr/balances" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Dipendente<select name="user_id"><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= View::e($u['name']) ?></option><?php endforeach;?></select></label><label class="field">Anno<input type="number" name="balance_year" value="<?= date('Y') ?>"></label><label class="field">Tipo<select name="leave_type"><option>HOLIDAY</option><option>PERMIT</option><option>ROL</option><option>OTHER</option></select></label><label class="field">Saldo iniziale<input type="number" step="0.25" name="opening_hours" value="0"></label><label class="field">Maturate<input type="number" step="0.25" name="accrued_hours" value="0"></label><label class="field">Rettifiche<input type="number" step="0.25" name="adjusted_hours" value="0"></label><input type="hidden" name="used_hours" value="0"><div class="form-actions full-width"><button class="button">Aggiorna saldo</button></div></form><div class="table-wrap"><table><thead><tr><th>Dipendente</th><th>Anno</th><th>Tipo</th><th>Disponibili</th><th>Usate</th></tr></thead><tbody><?php foreach($balances as $b):?><tr><td><?= View::e($b['user_name']) ?></td><td><?= (int)$b['balance_year'] ?></td><td><?= View::e($b['leave_type']) ?></td><td><?= View::e($b['available_hours']) ?></td><td><?= View::e($b['used_hours']) ?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card form-card"><div class="card-header"><div><h2>Nuova elaborazione paghe</h2><p>CONFIGURED_RATES è una simulazione; IMPORTED_PAYSLIPS acquisisce dati certificati.</p></div></div><form method="post" action="/operations/hr/payroll" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Dal<input type="date" name="period_start" required></label><label class="field">Al<input type="date" name="period_end" required></label><label class="field">Modalità<select name="calculation_mode"><option>IMPORTED_PAYSLIPS</option><option>CONFIGURED_RATES</option></select></label><div class="form-actions full-width"><button class="button primary">Crea elaborazione</button></div></form></section></div>
<details class="card setup-panel"><summary><span class="metric-icon violet">€</span><span><strong>Configurazioni retributive</strong><small>Tariffe interne per simulazioni gestionali; non sostituiscono il cedolino del consulente.</small></span><?= View::icon('chevron','setup-chevron') ?></summary><form method="post" action="/operations/hr/payroll-configs" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Dipendente<select name="user_id"><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= View::e($u['name']) ?></option><?php endforeach;?></select></label><label class="field">Codice / matricola<input name="employee_code" required></label><label class="field">Valida dal<input type="date" name="valid_from" required></label><label class="field">Ore settimanali<input type="number" step="0.25" name="standard_weekly_hours" value="40"></label><label class="field">Tariffa oraria<input type="number" step="0.0001" name="hourly_rate" value="0"></label><label class="field">Lordo mensile fisso<input type="number" step="0.01" name="fixed_monthly_amount" value="0"></label><label class="field">Moltiplicatore straordinari<input type="number" step="0.0001" name="overtime_multiplier" value="1.3"></label><label class="field">Contributi dipendente %<input type="number" step="0.0001" name="inps_rate" value="0"></label><label class="field">Contributi datore %<input type="number" step="0.0001" name="employer_contribution_rate" value="0"></label><label class="field">INAIL %<input type="number" step="0.0001" name="inail_rate" value="0"></label><label class="field">Ritenuta gestionale %<input type="number" step="0.0001" name="tax_rate" value="0"></label><div class="form-actions full-width"><button class="button primary">Salva configurazione</button></div></form></details>
<section class="card"><div class="card-header"><h2>Elaborazioni paghe</h2></div><div class="table-wrap"><table><thead><tr><th>Periodo</th><th>Modalità</th><th>Dipendenti</th><th>Lordo</th><th>Netto</th><th>Stato</th><th>Validazione</th><th>Azioni</th></tr></thead><tbody><?php foreach($runs as $r):?><tr><td class="primary-cell"><a href="/operations/hr?run=<?= (int)$r['id'] ?>"><?= View::e($r['period_label']) ?></a></td><td><?= View::e($r['calculation_mode']) ?></td><td><?= (int)$r['employees_count'] ?></td><td><?= View::money($r['gross_total']) ?></td><td><?= View::money($r['net_total']) ?></td><td><span class="badge status-<?= strtolower($r['status']) ?>"><?= View::e($r['status']) ?></span></td><td><?= View::e($r['professional_validation_reference']??'—') ?></td><td><div class="inline-actions"><?php if($r['status']==='DRAFT'&&$r['calculation_mode']==='CONFIGURED_RATES'):?><form method="post" action="/operations/hr/payroll/<?= (int)$r['id'] ?>/calculate"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button">Calcola simulazione</button></form><?php elseif($r['status']==='DRAFT'&&$r['calculation_mode']==='IMPORTED_PAYSLIPS'):?><form method="post" action="/operations/hr/payroll/<?= (int)$r['id'] ?>/import" enctype="multipart/form-data" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="file" name="payslips" accept=".csv,text/csv" required><button class="button">Importa CSV</button></form><?php elseif($r['status']==='CALCULATED'&&$r['calculation_mode']==='IMPORTED_PAYSLIPS'):?><form method="post" action="/operations/hr/payroll/<?= (int)$r['id'] ?>/confirm" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input name="professional_validation_reference" placeholder="Rif. consulente" required><button class="button primary">Valida e blocca</button></form><?php elseif($r['status']==='CALCULATED'):?><span class="muted">Simulazione non contabilizzabile</span><?php elseif($r['status']==='CONFIRMED'):?><form method="post" action="/operations/hr/payroll/<?= (int)$r['id'] ?>/paid"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Segna pagata</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($selectedRun):?><section class="card"><div class="card-header"><div><h2>Dettaglio <?= View::e($selectedRun['period_label']) ?></h2><p><?= View::e($selectedRun['calculation_mode']) ?> · schema <?= View::e($selectedRun['schema_version']) ?></p></div></div><div class="table-wrap"><table><thead><tr><th>Dipendente</th><th>Ore</th><th>Straordinari</th><th>Lordo</th><th>Contributi dip.</th><th>Contributi datore</th><th>Imposte</th><th>Rimborsi</th><th>Trattenute</th><th>Netto</th><th>Costo azienda</th><th>Fonte</th></tr></thead><tbody><?php foreach($payrollDetails as $d):?><tr><td class="primary-cell"><?= View::e($d['employee_name']) ?></td><td><?= View::e($d['regular_hours']) ?></td><td><?= View::e($d['overtime_hours']) ?></td><td><?= View::money($d['gross_amount']) ?></td><td><?= View::money($d['contributions_amount']) ?></td><td><?= View::money($d['employer_contributions_amount']) ?></td><td><?= View::money($d['tax_amount']) ?></td><td><?= View::money($d['reimbursements_amount']) ?></td><td><?= View::money($d['deductions_amount']) ?></td><td><?= View::money($d['net_amount']) ?></td><td><?= View::money($d['employer_cost']) ?></td><td><?= View::e($d['source_reference']??'') ?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php endif;?>
